const body = $input.first().json.body;
const phone = (body?.phone || '').toString().trim();
const otp   = (body?.otp   || '').toString().trim();

if (!phone || !otp) {
  return [{ json: { valid: false, status: 400, error: 'Phone and OTP are required' } }];
}
if (!/^[6-9]\d{9}$/.test(phone)) {
  return [{ json: { valid: false, status: 422, error: 'Invalid phone number' } }];
}
if (!/^\d{6}$/.test(otp)) {
  return [{ json: { valid: false, status: 422, error: 'OTP must be exactly 6 digits' } }];
}

return [{ json: { valid: true, phone, otp } }];

const session = $('Get OTP Session').first().json;
const { phone, otp } = $('Validate Input').first().json;

if (!session?.id) {
  return [{ json: { verified: false, status: 404, error: 'No OTP found. Please request a new one.', sessionId: null } }];
}
if (Number(session.verified) === 1) {
  return [{ json: { verified: false, status: 409, error: 'OTP already used. Please request a new one.', sessionId: session.id } }];
}
if (Number(session.attempts) >= 5) {
  return [{ json: { verified: false, status: 429, error: 'Too many failed attempts. Request a new OTP.', sessionId: session.id } }];
}
if (new Date(session.expires_at) < new Date()) {
  return [{ json: { verified: false, status: 410, error: 'OTP has expired. Please request a new one.', sessionId: session.id } }];
}

